func testSpec(id Identity, generation uint64) Spec {
	return Spec{Schema: Schema, Identity: id, Generation: generation, RequiresBinary: 1, Services: []Service{
		{Role: "api", Profile: Profile{Resources: placement.Resources{CPU: 1, MemoryBytes: 1 << 30, DiskBytes: 1 << 30},
			Args: []string{"--port", "8080"}, Env: map[string]string{"MODE": "api"}}},
		{Role: "web", Profile: Profile{Resources: placement.Resources{CPU: 2, MemoryBytes: 2 << 30, DiskBytes: 1 << 30}},
			Spec: &workload.ServiceSpec{Role: "web", Environment: "production", Kind: workload.KindStateless,
				Replicas: workload.ReplicaBounds{Min: 1, Max: 3}}},
	}}
}

func ValidatePin(p Pin) error {
	if !regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+$`).MatchString(p.Version) {
		return errors.New("NetBird pin needs version, archives and enrollment_config")
	}
	for _, arch := range []string{"arm64", "amd64"} {
		a, _ := p.Archive(arch)
		expected := fmt.Sprintf("https://github.com/netbirdio/netbird/releases/download/v%s/netbird_%s_linux_%s.tar.gz", p.Version, p.Version, arch)
		if a.URL != expected {
			return fmt.Errorf("invalid NetBird %s archive source", arch)
		}
		if a.Bytes <= 0 || a.Bytes > MaxBinaryBytes {
			return fmt.Errorf("invalid NetBird %s archive size", arch)
		}
		if !SHA256Pattern.MatchString(a.SHA256) || !SHA256Pattern.MatchString(a.BinarySHA256) {
			return fmt.Errorf("invalid NetBird %s SHA-256", arch)
		}
	}
	return nil
}

func ValidatePinJSON(raw []byte) (Pin, error) {
	var pin Pin
	keys, err := orderedKeys(raw)
	if err != nil {
		return pin, err
	}
	if !slices.Equal(keys, []string{"version", "archives", "enrollment_config"}) {
		return pin, errors.New("NetBird pin needs version, archives and enrollment_config")
	}
	if err = json.Unmarshal(raw, &pin, json.RejectUnknownMembers(true)); err != nil {
		return pin, err
	}
	var fields map[string]jsontext.Value
	if err = json.Unmarshal(raw, &fields); err != nil {
		return pin, err
	}
	keys, err = orderedKeys(fields["archives"])
	if err != nil {
		return pin, err
	}
	if !slices.Equal(keys, []string{"arm64", "amd64"}) {
		return pin, errors.New("NetBird archives must pin arm64 and amd64")
	}
	var archives map[string]jsontext.Value
	if err = json.Unmarshal(fields["archives"], &archives); err != nil {
		return pin, err
	}
	for _, arch := range []string{"arm64", "amd64"} {
		keys, err = orderedKeys(archives[arch])
		if err != nil {
			return pin, err
		}
		if !slices.Equal(keys, []string{"url", "bytes", "sha256", "binary_sha256"}) {
			return pin, fmt.Errorf("invalid NetBird %s archive source", arch)
		}
	}
	return pin, ValidatePin(pin)
}
func LoadPin(path string) (Pin, error) {
	var inputs map[string]jsontext.Value
	b, err := os.ReadFile(path)
	if err != nil {
		return Pin{}, err
	}
	if err = json.Unmarshal(b, &inputs); err != nil {
		return Pin{}, err
	}
	raw, ok := inputs["netbird"]
	if !ok {
		return Pin{}, errors.New("missing NetBird input pin")
	}
	return ValidatePinJSON(raw)
}

var managedVersionPattern = regexp.MustCompile(`^0\.80\.[0-9]+$`)
var runningVersionPattern = regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+$`)
var errManagedUnitNotEnabled = errors.New("NetBird service is disabled or missing")

func ValidateManagedVersion(version string) error {
	if !managedVersionPattern.MatchString(version) {
		return errors.New("managed NetBird pin must be a 0.80.x release")
	}
	return nil
}

func (cfg Config) normalized() (Config, error) {
	if cfg.ManagementURL == "" {
		cfg.ManagementURL = DefaultManagementURL
	}
	if cfg.Region == "" {
		cfg.Region = DefaultRegion
	}
	manager, err := normalizeManagerURL(cfg.ManagementURL)
	if err != nil {
		return Config{}, err
	}
	cfg.ManagementURL = manager
	if cfg.ManagementIP != "" {
		ip, err := netip.ParseAddr(cfg.ManagementIP)
		if err != nil || !ip.IsPrivate() || ip.Zone() != "" || ip.Is4In6() {
			return Config{}, errors.New("NetBird management_ip must be a private IPv4 or IPv6 address")
		}
		cfg.ManagementIP = ip.String()
	}
	if !ValidSecretID(cfg.Region, cfg.SetupKeySecretID) {
		return Config{}, errors.New("NetBird setup_key_secret_id must identify an OCI Vault secret in the configured region")
	}
	if cfg.AdminPATSecretID != "" && !ValidSecretID(cfg.Region, cfg.AdminPATSecretID) {
		return Config{}, errors.New("NetBird admin_pat_secret_id must identify an OCI Vault secret in the configured region")
	}
	if err := ValidatePeerNames(cfg.PeerNames); err != nil {
		return Config{}, err
	}
	return cfg, nil

func (n NetBird) Validate(cell string) error {
	if err := client.ValidatePin(n.Pin); err != nil {
		return err
	}
	if err := client.ValidateManagedVersion(n.Pin.Version); err != nil {
		return err
	}
	file := n.Pin.EnrollmentConfig
	if !client.SHA256Pattern.MatchString(file.SHA256) || path.Clean(file.Path) != file.Path ||
		!strings.HasPrefix(file.Path, "deploy/image/inputs/") || path.Ext(file.Path) != ".json" {
		return errors.New("NetBird enrollment input needs a pinned JSON file under deploy/image/inputs")
	}
	if err := n.Enrollment.Validate(); err != nil {
		return err
	}
	region, ok := catalog.LookupName(cell)
	if !ok {
		return errors.New("NetBird enrollment requires a catalog cell")
	}
	effectiveRegion := n.Enrollment.Region
	if effectiveRegion == "" {
		effectiveRegion = netbird.DefaultRegion
	}
	if effectiveRegion != region.OCIRegion {
		return errors.New("NetBird enrollment region differs from the cell")
	}
	for _, name := range n.Enrollment.PeerNames {
		if !strings.HasPrefix(name, "ts-"+cell+"-") && !strings.HasPrefix(name, cell+"-") {
			return errors.New("NetBird peer name differs from the cell")
		}
	}
	return nil
}

func (s Spec) Validate() error {
	if s.Schema != Schema {
		return fmt.Errorf("%w: schema", ErrInvalid)
	}
	if err := s.Identity.Validate(); err != nil {
		return err
	}
	if s.RequiresBinary < s.Level() || s.RequiresBinary > BinaryLevel {
		return fmt.Errorf("%w: requires_binary must be between %d and %d", ErrInvalid, s.Level(), BinaryLevel)
	}
	for index, service := range s.Services {
		if !tokenRE.MatchString(service.Role) {
			return fmt.Errorf("%w: role %q", ErrInvalid, service.Role)
		}
		if index > 0 && s.Services[index-1].Role >= service.Role {
			return fmt.Errorf("%w: services must be sorted by role without repeats", ErrInvalid)
		}
		for i, actor := range service.Releasers {
			if !tokenRE.MatchString(actor) || i > 0 && service.Releasers[i-1] >= actor {
				return fmt.Errorf("%w: service %q releasers must be sorted actor names without repeats", ErrInvalid, service.Role)
			}
		}
		if service.Spec != nil {
			if service.Spec.Role != service.Role {
				return fmt.Errorf("%w: service %q has a spec for role %q", ErrInvalid, service.Role, service.Spec.Role)
			}
			if err := service.Spec.Validate(); err != nil {
				return fmt.Errorf("service %q: %w", service.Role, err)
			}
		}
	}

if s.NetBird != nil {
	if err := s.NetBird.Validate(s.Identity.Cell); err != nil {
		return fmt.Errorf("%w: netbird: %w", ErrInvalid, err)
	}
}
return nil

func (s Spec) Level() uint64 {
	level := uint64(1)
	for _, service := range s.Services {
		if len(service.Profile.Secrets) != 0 {
			level = 2
		}
	}
	if len(s.HostImages) != 0 {
		level = 4
	}
	if s.OCIDesired != nil {
		level = max(level, 7)
	}
	if len(s.Signers) != 0 {
		level = max(level, 8)
	}
	if s.LaunchImage != "" {
		level = 9
	}
	if s.ArtifactStore != nil {
		level = 10
	}
	if s.Atlas != nil {
		level = 11
	}
	if s.ReleaseFence != nil {
		level = 12
		if slices.ContainsFunc(s.ReleaseFence.BackendSets, func(set FencedSet) bool { return set.MinServing != 0 }) {
			level = 13
		}
		if slices.ContainsFunc(s.ReleaseFence.BackendSets, func(set FencedSet) bool { return set.Role != "" }) {
			level = 14
		}
		if s.ReleaseFence.Canary != nil {
			level = 15
		}
	}
	if s.MachinesAPI != nil {
		level = 16
	}
	if slices.ContainsFunc(s.HostGrants, func(grant HostGrant) bool { return grant.Controller != "" }) {
		level = 17
	}
	if s.Dashboard != nil {
		level = 18
	}
	if slices.ContainsFunc(s.Signers, func(signer TrustedSigner) bool { return signer.CanInstallMaterial }) {
		level = 19
	}
	if s.NetBird != nil {
		level = 20
	}
	if s.MachinesAPI != nil && s.MachinesAPI.PlatformOrganizationID != "" {
		level = 21
	}
	return level
}

// Enrollment widens the node's Vault and manager authority. Once it is
// authorized, changing only verified client artifacts is an ordinary bump.
if next.NetBird != nil && (current.NetBird == nil || !reflect.DeepEqual(current.NetBird.Enrollment, next.NetBird.Enrollment)) {
	changes = append(changes, "netbird enrollment")
}

	switch before, after := current.NetBird, next.NetBird; {
	case before == nil && after != nil:
		plan.NetBird = "added"
	case before != nil && after == nil:
		plan.NetBird = "removed"
	case before != nil && !reflect.DeepEqual(before, after):
		plan.NetBird = "updated"
	}
	return plan, nil
}

// Empty reports whether the plan changes nothing.
func (p Plan) Empty() bool {
	return len(p.Added)+len(p.Updated)+len(p.Removed)+len(p.HostGrants)+len(p.HostImages) == 0 &&
		p.OCIDesired == "" && len(p.Signers) == 0 &&
		p.LaunchImage == "" && p.ArtifactStore == "" && p.Atlas == "" && p.ReleaseFence == "" && p.MachinesAPI == "" &&
		p.Dashboard == "" && p.NetBird == ""
}

