		return fmt.Errorf("unknown command %q; use ts-orch --help", args[0])
	}
}

func runOCIRegion(ctx context.Context, args []string, output io.Writer) error {
	if len(args) == 0 || args[0] == "--help" || args[0] == "-h" || args[0] == "help" {
		_, err := io.WriteString(output, "Usage: ts-orch oci-region <command> [flags]\n\n  preview       Inventory, estimate, admit, and inspect regional resources\n  foundation    Create the plan's missing compartments, network, Vault, IAM and buckets (dry run unless --apply)\n  peer          Create the private DRG/RPC peering of two cells that inspect-private-peer checks (dry run unless --apply)\n  attempt       Resume an admitted regional bootstrap attempt\n  public-api    Preview, certify and apply the cell's Cloudflare-fronted load balancer\n  dns           Set Full (strict), origin pulls and proxied A records in Cloudflare (dry run unless --apply)\n  teardown      Delete a reviewed cell teardown plan's OCI resources in dependency order\n")
		return err
	}
	switch args[0] {
	case "preview", "attempt":
		var diagnostics bytes.Buffer
		var code int
		if args[0] == "preview" {
			code = ociregion.PreviewRun(ctx, args[1:], output, &diagnostics)
		} else {
			code = attempt.Run(ctx, args[1:], output, &diagnostics)
		}
		return commandStatus(ctx, code, &diagnostics)
	case "foundation":
		return foundation.Run(ctx, args[1:], output)
	case "peer":
		return foundation.RunPeer(ctx, args[1:], output)
	case "public-api":
		return publicapi.Run(ctx, args[1:], output)
	case "dns":
		return publicapi.RunDNS(ctx, args[1:], output)
	case "teardown":
		return teardown.Run(ctx, args[1:], output)
	default:
		return fmt.Errorf("unknown oci-region command %q", args[0])
	}
}

func commandStatus(ctx context.Context, code int, diagnostics *bytes.Buffer) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if code == 0 {
		return nil
	}
	message := strings.TrimSpace(diagnostics.String())
	if message == "" {
		message = fmt.Sprintf("command failed with exit code %d", code)
	}
	return fmt.Errorf("%s", message)
}

func runQualification(ctx context.Context, args []string, out io.Writer) error {
	if len(args) == 0 || args[0] == "--help" || args[0] == "help" || args[0] == "-h" {
		_, err := io.WriteString(out, "Usage: ts-orch qualification <command> [flags]\n\n  real-caller    Qualify admitted real OCI callers\n  firecracker    Run disposable Firecracker qualification\n")
		return err
	}
	var diagnostics bytes.Buffer
	switch args[0] {
	case "real-caller":
		return commandStatus(ctx, realcaller.Run(ctx, args[1:], out, &diagnostics), &diagnostics)
	case "firecracker":
		if len(args) == 1 || args[1] == "--help" || args[1] == "help" || args[1] == "-h" {
			_, err := io.WriteString(out, "Usage: ts-orch qualification firecracker <generic|memberstatus|managedmember|production|prepare-base> [flags]\n")
			return err
		}
		var err error
		switch args[1] {
		case "generic":
			err = firecracker.RunGeneric(ctx, args[2:], out, &diagnostics)
		case "production":
			err = firecracker.RunProduction(ctx, args[2:], out, &diagnostics)
		case "prepare-base":
			err = firecracker.RunPrepareBase(ctx, args[2:], out, &diagnostics)
		case "memberstatus":
			err = memberstatus.Run(ctx, args[2:], out, &diagnostics)
		case "managedmember":
			err = firecracker.RunManagedMember(ctx, args[2:], out, &diagnostics)
		default:
			return fmt.Errorf("unknown Firecracker qualification %q", args[1])
		}
		if err != nil {
			return err
		}
		return nil
	default:
		return fmt.Errorf("unknown qualification command %q", args[0])
	}
}

func NewWriter(destination io.Writer) *Writer {
	return &Writer{destination: destination}
}

func (writer *Writer) Write(contents []byte) (int, error) {
	if writer.err != nil {
		return 0, writer.err
	}
	written, err := writer.destination.Write(contents)
	if err == nil && written != len(contents) {
		err = io.ErrShortWrite
	}
	writer.err = err
	return written, err
}

func (writer *Writer) Err() error { return writer.err }

// Run requires an explicit opt-in; ordinary tests never contact production.
func Run(ctx context.Context, args []string, output io.Writer) (err error) {
	out := commandio.NewWriter(output)
	defer func() { err = errors.Join(err, out.Err()) }()
	if err := ctx.Err(); err != nil {
		return err
	}
	f := flag.NewFlagSet("verify", flag.ContinueOnError)
	f.SetOutput(out)
	live := f.Bool("live", os.Getenv("TS_VERIFY_LIVE") == "1", "opt in to read-only production requests")
	region := f.String("region", env("E2E_REGION", "gru-1"), "expected cell/region")
	cell := f.String("cell", env("TS_VERIFY_CELL", "gru"), "expected controller manifest cell (distinct from TerraBase region)")
	tb := f.String("terrabase-url", env("E2E_TERRABASE_URL", "https://gru.api.terrascale.tech"), "TerraBase origin")
	auth := f.String("auth-url", env("E2E_AUTH_URL", "https://gru.auth.terrascale.tech"), "ts-auth origin")
	dash := f.String("dashboard-url", env("E2E_DASHBOARD_URL", "https://dash.terrascale.tech"), "dashboard origin")
	status := f.String("status-url", env("E2E_STATUS_URL", "https://status.terrascale.tech"), "status origin")
	orch := f.String("orchestrator-url", os.Getenv("TS_VERIFY_ORCHESTRATOR_URL"), "controller observability origin (HTTPS or loopback tunnel)")
	timeout := f.Duration("timeout", 10*time.Second, "deadline per GET")
	if err := f.Parse(args); errors.Is(err, flag.ErrHelp) {
		return nil
	} else if err != nil {
		return err
	}
	if f.NArg() != 0 || *timeout <= 0 || *region == "" || *cell == "" {
		return errors.New("verify requires no positional arguments, a region and a positive timeout")
	}
	if !*live {
		return errors.New("verify requires --live or TS_VERIFY_LIVE=1; no requests sent")
	}

const usage = `Usage: ts-orch dashboard check --gru-token-file FILE --sfo-token-file FILE [--netbird COMMAND] [--timeout 5s]

