		query.Set("max", strconv.Itoa(*maximum))
		query.Set("start", *start)
		query.Set("end", *end)
		if *rate {
			query.Set("rate", "1")
		}
		if *maximum < 1 {
			return errors.New("--max must be between 1 and 512")
		}
		if _, err := observability.ParseHistoryQuery(query, time.Now()); err != nil {
			return err
		}
	case "events":
		if *limit < 1 || *limit > observability.DefaultEventCapacity {
			return errors.New("--limit must be between 1 and 2048")
		}
		query.Set("limit", strconv.Itoa(*limit))
		query.Set("after", strconv.FormatUint(*after, 10))
	case "decisions", "summary", "logs":
		var err error
		query, err = feature.query(view, *limit, *service)
		if err != nil {
			return err
		}
	case "credentials", "backups", "netbird":
		var err error
		path, err = observeOperationPath(view, *database, *partition)
		if err != nil {
			return err
		}
	}
	if isObserveResource(view) {
		var err error
		path, err = observeResourcePath(view, *cell, *node, *service, *volume, *tenant, *function)
		if err != nil {
			return err
		}
	}

	ctx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	urls, token, err := observeAccess(ctx, *region, *origin, *tokenFile)
	if err != nil {
		return err
	}
	transport := &http.Transport{Proxy: nil, IdleConnTimeout: 30 * time.Second}
	defer transport.CloseIdleConnections()
	client := &http.Client{Transport: transport, Timeout: 15 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
	var failures []error
	var partialData []byte
	var partialSource string
	type answer struct {
		source string
		data   []byte
		err    error
	}
	answers := make(chan answer, len(urls))
	for _, base := range urls {
		go func() {
			resourcePath := path
			if isObserveResource(view) && view != "regions" && *cell == "" {
				data, err := observeFetch(ctx, client, base, "/v1/regions", nil, token)
				if err != nil {
					answers <- answer{source: base, err: err}
					return
				}
				local, err := observeLocalCell(data)
				if err != nil {
					answers <- answer{source: base, err: err}
					return
				}
				resourcePath, err = observeResourcePath(view, local, *node, *service, *volume, *tenant, *function)
				if err != nil {
					answers <- answer{source: base, err: err}
					return
				}
			}
			data, err := observeFetch(ctx, client, base, resourcePath, query, token)
			answers <- answer{base, data, err}
		}()
	}
gather:
	for range urls {
		var result answer
		select {
		case result = <-answers:
		case <-ctx.Done():
			failures = append(failures, ctx.Err())
			break gather
		}
		base, data, err := result.source, result.data, result.err
		if err != nil {
			failures = append(failures, err)
			continue
		}
		var buffer strings.Builder
		partial, err := writeObserve(&buffer, view, *format, base, *search, data)
		if err != nil {
			failures = append(failures, err)
			continue
		}
		if partial {
			if partialData == nil {
				partialData, partialSource = data, base
			}
			continue
		}
		_, err = io.WriteString(out, buffer.String())
		return err
	}
	if partialData != nil {
		_, err := writeObserve(out, view, *format, partialSource, *search, partialData)
		return errors.Join(errors.New("observe returned partial or truncated data; inspect the reported gaps"), err)
	}
	return fmt.Errorf("observe %s: %w", view, errors.Join(failures...))
}

func observeAccess(ctx context.Context, region, origin, tokenFile string) ([]string, string, error) {
	var urls []string
	var token string
	if (origin == "") != (tokenFile == "") {
		return nil, "", errors.New("diagnostic access requires --url and --token-file together")
	}
	if origin == "" {
		access, err := controlaccess.Resolve(ctx, region)
		if err != nil {
			if errors.Is(err, controlaccess.ErrPending) {
				return nil, "", fmt.Errorf("observe access pending: %w", err)
			}
			return nil, "", fmt.Errorf("resolve admitted observe access: %w", err)
		}
		urls, token = access.URLs, access.Token
	}
	if tokenFile != "" {
		file, err := os.Open(tokenFile)
		if err != nil {
			return nil, "", fmt.Errorf("open observe token file: %w", err)
		}
		defer file.Close()
		info, err := file.Stat()
		if err != nil || !info.Mode().IsRegular() || info.Mode().Perm()&0077 != 0 {
			return nil, "", errors.New("observe token file must be a private regular file")
		}
		data, err := io.ReadAll(io.LimitReader(file, 4097))
		if err != nil {
			return nil, "", err
		}
		token = strings.TrimSpace(string(data))
		clear(data)
		if len(data) > 4096 {
			return nil, "", errors.New("observe token file exceeds 4096 bytes")
		}
	}
	if len(token) < 32 || len(token) > 4096 || strings.ContainsAny(token, " \t\r\n\x00") {
		return nil, "", errors.New("observe requires one 32-4096 byte bearer token from OCI Vault or a private file")
	}
	if origin != "" {
		urls = []string{origin}
	}
	if len(urls) == 0 {
		return nil, "", fmt.Errorf("admitted management endpoints are unavailable: %w", controlaccess.ErrPending)
	}
	if len(urls) > 64 {
		return nil, "", errors.New("observe endpoint inventory exceeds 64 controllers")
	}
	// Validate every destination before sending a credential to any of them.
	for _, base := range urls {
		if _, err := observeURL(base); err != nil {
			return nil, "", err
		}
	}
	return urls, token, nil
}

func observeURL(base string) (*url.URL, error) {
	u, err := url.Parse(base)
	if err != nil || u.Host == "" || u.User != nil || u.RawQuery != "" || u.Fragment != "" || (u.Path != "" && u.Path != "/") || (u.Scheme != "https" && u.Scheme != "http") {
		return nil, errors.New("observe endpoint must be an HTTP(S) origin without credentials, path, query or fragment")
	}
	if u.Scheme == "http" {
		host := u.Hostname()
		ip, _ := netip.ParseAddr(host)
		if host != "localhost" && !ip.IsLoopback() && !netip.MustParsePrefix("10.200.0.0/16").Contains(ip) && !strings.HasSuffix(host, ".nb.ts.internal") {
			return nil, errors.New("HTTP observe endpoints require loopback or the encrypted NetBird overlay")
		}
	}
	return u, nil
}

func observeFetch(ctx context.Context, client *http.Client, base, path string, query url.Values, token string) ([]byte, error) {
	u, err := observeURL(base)
	if err != nil {
		return nil, err
	}
	u.Path = path
	u.RawQuery = query.Encode()
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Authorization", "Bearer "+token)
	req.Header.Set("Accept", "application/json")
	response, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("%s: request failed: %w", base, err)
	}
	defer response.Body.Close()
	if response.StatusCode == http.StatusUnauthorized || response.StatusCode == http.StatusForbidden {
		return nil, fmt.Errorf("%s: authentication denied (HTTP %d); verify the regional Vault credential", base, response.StatusCode)
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, (8<<20)+1))
	if err != nil {
		return nil, fmt.Errorf("%s: response read failed", base)
	}
	if len(data) > 8<<20 {
		return nil, fmt.Errorf("%s: response exceeds 8 MiB", base)
	}
	if len(data) == 0 || strings.TrimSpace(string(data)) == "null" {
		return nil, fmt.Errorf("%s: API returned empty observation", base)
	}
	if response.StatusCode != http.StatusOK && !observeResourceError(path, response.StatusCode, data) && !observeOperationError(path, response.StatusCode, data) {
		return nil, fmt.Errorf("%s: API returned HTTP %d", base, response.StatusCode)
	}
	return data, nil
}

func writeObserve(out io.Writer, view, format, source, search string, data []byte) (bool, error) {
	var value any
	partial := false
	table := tabwriter.NewWriter(out, 0, 0, 2, ' ', 0)
	switch view {
	case "foundation", "credentials", "backups", "netbird":
		var err error
		value, partial, err = writeObserveOperation(table, view, format, data)
		if err != nil {
			return false, err
		}
	case "decisions", "insights", "summary", "logs":
		var err error
		value, partial, err = writeObserveFeature(table, view, format, data)
		if err != nil {
			return false, err
		}
	case "regions", "region", "nodes", "node", "services", "service", "functions", "function", "volumes", "volume":
		var err error
		value, partial, err = writeObserveResource(table, view, format, data)
		if err != nil {
			return false, err
		}
	case "metrics":
		var result observability.CatalogResult
		if err := json.Unmarshal(data, &result); err != nil {
			return false, errors.New("invalid metric catalog JSON")
		}
		if result.Version != 1 {
			return false, errors.New("unsupported metric catalog version")
		}
		filtered := result.Metrics[:0]
		for _, metric := range result.Metrics {
			if strings.Contains(strings.ToLower(metric.Name+" "+metric.Description+" "+metric.Source), strings.ToLower(search)) {
				filtered = append(filtered, metric)
			}
		}
		result.Metrics = filtered
		partial = result.Truncated || result.State != "available"
		value = result
		if format == "table" {
			fmt.Fprintf(table, "STATE\t%s\tOBSERVED\t%s\tTRUNCATED\t%t\n", result.State, result.ObservedAt.Format(time.RFC3339), result.Truncated)
			fmt.Fprintln(table, "METRIC\tTYPE\tUNIT\tSOURCE\tSTATE\tHISTORY\tTIERS\tRETENTION seconds\tLABELS\tDESCRIPTION")
			for _, metric := range result.Metrics {
				fmt.Fprintf(table, "%s\t%s\t%s\t%s\t%s\t%s\t%s\t%d\t%s\t%s\n", metric.Name, metric.Type, metric.Unit, metric.Source, metric.State, metric.HistoryState, strings.Join(metric.HistoryTiers, ","), metric.HistoryRetentionSeconds, strings.Join(metric.Labels, ","), metric.Description)
				if len(metric.Unsupported) > 0 {
					fmt.Fprintf(table, "  UNSUPPORTED\t%s\n", strings.Join(metric.Unsupported, ","))
				}
				for _, sample := range metric.Samples {
					fmt.Fprintf(table, "  SAMPLE\t%s\t%s\n", sample.Name, sample.Value)
				}
			}
		}
	case "history":
		var result observability.CatalogHistory
		if err := json.Unmarshal(data, &result); err != nil {
			return false, errors.New("invalid history JSON")
		}
		if result.Version != 1 {
			return false, errors.New("unsupported history version")
		}
		partial = result.Truncated || result.Pending || result.Incomplete || result.State != "available"
		value = result
		if format == "table" {
			fmt.Fprintf(table, "STATE\t%s\tREASON\t%s\nTRUNCATED\t%t\tPENDING\t%t\tINCOMPLETE\t%t\n", result.State, result.Reason, result.Truncated, result.Pending, result.Incomplete)
			fmt.Fprintf(table, "RETENTION START\t%s\tINTERVAL seconds\t%g\tDROPPED SERIES\t%d\n", result.RetentionStart.Format(time.RFC3339), result.IntervalSeconds, result.DroppedSeries)
			fmt.Fprintln(table, "METRIC\tLABELS\tTIER\tTIME\tVALUE\tMIN\tMAX")
			for _, series := range result.Series {
				fmt.Fprintf(table, "SERIES\t%s\tSTALE\t%t\tGAPS\t%t\tLAST OBSERVED\t%s\n", series.Metric, series.Stale, series.Gaps, series.LastObservedAt.Format(time.RFC3339))
				labels, _ := json.Marshal(series.Labels)
				for _, point := range series.Points {
					fmt.Fprintf(table, "%s\t%s\t%s\t%s\t%g\t%g\t%g\n", series.Metric, labels, series.Tier, point.Time.Format(time.RFC3339), point.Value, point.Min, point.Max)
				}
			}
		}
	case "snapshot":
		var result observability.MemberSnapshot
		if err := json.Unmarshal(data, &result); err != nil || result.Member == "" || result.Version != observability.SnapshotVersion {
			return false, errors.New("invalid member snapshot JSON")
		}
		value = result
		partial = len(result.Errors) > 0 || result.MetricsTruncated
		if format == "table" {
			writeObserveMember(table, result)
		}
	case "cluster":
		var result observability.ClusterSnapshot
		if err := json.Unmarshal(data, &result); err != nil || result.Cell == "" {
			return false, errors.New("invalid cluster snapshot JSON")
		}
		value = result
		partial = len(result.Missing) > 0 || len(result.Members) == 0
		if format == "table" {
			fmt.Fprintf(table, "CELL\t%s\tOBSERVED\t%s\nMISSING\t%s\n", result.Cell, result.ObservedAt.Format(time.RFC3339), strings.Join(result.Missing, ","))
		}
		for _, member := range result.Members {
			partial = partial || len(member.Errors) > 0 || member.MetricsTruncated
			if format == "table" {
				writeObserveMember(table, member)
			}
		}
	case "events":
		var result []observability.Event
		if err := json.Unmarshal(data, &result); err != nil {
			return false, errors.New("invalid event JSON")
		}
		value = result
		if format == "table" {
			fmt.Fprintln(table, "SEQUENCE\tTIME\tLEVEL\tCOMPONENT\tMESSAGE\tATTRIBUTES")
			for _, event := range result {
				attrs, _ := json.Marshal(event.Attrs)
				fmt.Fprintf(table, "%d\t%s\t%s\t%s\t%s\t%s\n", event.Sequence, event.Time.Format(time.RFC3339), event.Level, event.Component, event.Message, attrs)
			}
		}
	}
	if format == "json" {
		err := json.MarshalWrite(out, struct {
			Version int    `json:"version"`
			View    string `json:"view"`
			Source  string `json:"source"`
			Partial bool   `json:"partial"`
			Data    any    `json:"data"`
		}{1, view, source, partial, value}, jsontext.WithIndent("  "))
		if err == nil {
			_, err = io.WriteString(out, "\n")
		}
		return partial, err
	}
	return partial, table.Flush()
}

func writeObserveMember(out io.Writer, member observability.MemberSnapshot) {
	fmt.Fprintf(out, "MEMBER\t%s\tCELL\t%s\tROLE\t%s\tREADY\t%t\tOBSERVED\t%s\n", member.Member, member.Cell, member.Role, member.Ready, member.ObservedAt.Format(time.RFC3339))
	for _, check := range member.Checks {
		fmt.Fprintf(out, "CHECK\t%s\tOK\t%t\t%s\n", check.Name, check.OK, check.Detail)
	}
	for _, name := range slices.Sorted(maps.Keys(member.Errors)) {
		fmt.Fprintf(out, "UNAVAILABLE\t%s\t%s\n", name, member.Errors[name])
	}
	fmt.Fprintf(out, "METRICS TRUNCATED\t%t\n", member.MetricsTruncated)
}

func NewTokenServer(config Config, token string, deps ServerDeps) (*Server, error) {
	checked, err := checkBearerToken([]byte(token))
	if err != nil {
		return nil, err
	}
	// The token stands in for the file Validate requires off loopback.
	config.BearerTokenFile = "token"
	if err := config.Validate(); err != nil {
		return nil, err
	}
	return newServer(config, checked, deps)
}

func newServer(config Config, token []byte, deps ServerDeps) (*Server, error) {
	if deps.Registry == nil || deps.Health == nil {
		return nil, errors.New("observability server requires a registry and health checks")
	}
	manager := &sessions{secure: config.TLSCertFile != ""}
	if deps.LocalSessions {
		manager.local = make(map[string]struct{})
	}
	server := &Server{mux: http.NewServeMux(), deps: deps, sessions: manager, token: token}
	server.catalog = &metricCatalog{registry: deps.Registry}
	if deps.Sessions != nil && token != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := server.SetSessionStore(ctx, deps.Sessions); err != nil {
			return nil, err
		}
	}
	server.mux.HandleFunc("GET /healthz", func(writer http.ResponseWriter, _ *http.Request) {
		writePlain(writer, http.StatusOK, "ok\n")
	})
	server.mux.HandleFunc("GET /readyz", server.readyz)
	server.Handle("GET /metrics", http.HandlerFunc(server.metrics))
	server.HandleAuthenticated("GET /v1/metrics/catalog", http.HandlerFunc(server.metricCatalogHTTP))
	if deps.Snapshots != nil {
		server.HandleSnapshots(deps.Snapshots)
	}
	if deps.Cluster != nil {
		server.HandleCluster(deps.Cluster)
	}
	if deps.Events != nil {
		server.Handle("GET /v1/events", http.HandlerFunc(server.events))
	}
	return server, nil
}

// HandleSnapshots mounts GET /v1/snapshot once a runtime finished wiring
// its providers. A listener started earlier serves health meanwhile. Calling
// it again replaces the source rather than mounting the route twice.
func (server *Server) HandleSnapshots(source SnapshotSource) {
	server.snapshots.Store(&source)
	server.snapshotOnce.Do(func() {
		server.Handle("GET /v1/snapshot", http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
			snapshot, err := (*server.snapshots.Load()).Snapshot(request.Context(),
				request.URL.Query().Get("metrics") == "1")
			if err != nil {
				writePlain(writer, http.StatusServiceUnavailable, "snapshot unavailable\n")
				return
			}
			writeJSON(writer, snapshot)
		}))
	})
}

// HandleCluster mounts GET /v1/cluster for a cell-wide aggregator. Calling it
// again replaces the aggregator.
func (server *Server) HandleCluster(source ClusterSource) {
	server.cluster.Store(&source)
	server.clusterOnce.Do(func() {
		server.Handle("GET /v1/cluster", http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
			snapshot, err := (*server.cluster.Load()).Cluster(request.Context(),
				request.URL.Query().Get("metrics") == "1")
			if err != nil {
				writePlain(writer, http.StatusServiceUnavailable, "cluster snapshot unavailable\n")
				return
			}
			writeJSON(writer, snapshot)
		}))
	})
}

// Handle mounts an authenticated read-only route. With a configured bearer
// token every request must present it, or a session cookie once HandleLogin
// mounted the dashboard login; on a tokenless loopback listener the loopback
// bind is the only control, as for the built-in routes.
func (server *Server) Handle(pattern string, handler http.Handler) {
	server.mux.Handle(pattern, server.authenticate(handler))
}

// HandleAuthenticated never grants tokenless loopback access to this API.
func (server *Server) HandleAuthenticated(pattern string, handler http.Handler) {
	server.Handle(pattern, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if server.token == nil {
			writePlain(w, http.StatusServiceUnavailable, "authenticated API requires a configured token\n")
			return
		}
		handler.ServeHTTP(w, r)
	}))

// ServeHTTP lets tests and an embedding mux exercise the routes directly.
func (server *Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	// A proxy hop would make the bind address meaningless as an access
	// control, exactly as for the host enrollment listener.
	if request.Header.Get("Forwarded") != "" || request.Header.Get("X-Forwarded-For") != "" ||
		request.Header.Get("X-Real-IP") != "" {
		writePlain(writer, http.StatusBadRequest, "proxied requests are not accepted\n")
		return
	}
	// Without a token the loopback bind is the only control, and DNS
	// rebinding defeats it for any route reachable under a hostname. Every
	// route of a tokenless listener, not only the dashboard's, therefore
	// requires an IP literal or localhost as the Host.
	if server.token == nil && !LiteralHost(request.Host) {
		writePlain(writer, http.StatusMisdirectedRequest, "address this listener by IP or localhost\n")
		return
	}
	server.mux.ServeHTTP(writer, request)
}

func (server *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if server.token != nil && !bearerMatches(request.Header.Get("Authorization"), server.token) {
			authenticated := false
			if request.Header.Get("Authorization") == "" && server.loginMounted.Load() {
				var err error
				authenticated, err = server.sessions.authenticated(request)
				if err != nil {
					writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
					return
				}
			}
			if !authenticated {
				if server.loginMounted.Load() && wantsLoginPage(request) {
					http.Redirect(writer, request, "/login?next="+url.QueryEscape(LocalRedirectPath(request.URL.RequestURI())),
						http.StatusSeeOther)
					return
				}
				writer.Header().Set("WWW-Authenticate", `Bearer realm="ts-orch"`)
				writePlain(writer, http.StatusUnauthorized, "unauthorized\n")
				return
			}
		}
		if server.token != nil && server.loginMounted.Load() && request.Header.Get("Authorization") == "" {
			if cookie, err := request.Cookie(SessionCookieName); err == nil {
				http.SetCookie(writer, server.sessions.cookie(cookie.Value))
			}
		}
		next.ServeHTTP(writer, request)
	})
}

func (server *Server) events(writer http.ResponseWriter, request *http.Request) {
	query := request.URL.Query()
	after, _ := strconv.ParseUint(query.Get("after"), 10, 64)
	limit, err := strconv.Atoi(query.Get("limit"))
	if err != nil || limit <= 0 || limit > DefaultEventCapacity {
		limit = 200
	}
	writeJSON(writer, server.deps.Events.Since(after, limit))
}

func writePlain(writer http.ResponseWriter, status int, body string) {
	writer.Header().Set("Content-Type", "text/plain; charset=utf-8")
	writer.Header().Set("Cache-Control", "no-store")
	writer.Header().Set("X-Content-Type-Options", "nosniff")
	writer.WriteHeader(status)
	_, _ = writer.Write([]byte(body))
}

func writeJSON(writer http.ResponseWriter, value any) {
	data, err := json.Marshal(value)
	if err != nil {
		writePlain(writer, http.StatusInternalServerError, "encode failed\n")
		return
	}
	writer.Header().Set("Content-Type", "application/json")
	writer.Header().Set("Cache-Control", "no-store")
	writer.Header().Set("X-Content-Type-Options", "nosniff")
	_, _ = writer.Write(append(data, '\n'))
}

func (server *Server) metricCatalogHTTP(writer http.ResponseWriter, request *http.Request) {
	result, err := server.catalog.Catalog(request.Context())
	if err != nil {
		writePlain(writer, http.StatusServiceUnavailable, "metric catalog unavailable\n")
		return
	}
	writeJSON(writer, result)
}

// HandleMetricHistory installs or replaces the history source shared by the
// catalog, dashboard and API. Callers must not mount HistoryHandler separately.
func (server *Server) HandleMetricHistory(source HistorySource) {
	if source == nil {
		return
	}
	server.catalog.history.Store(&source)
	server.historyOnce.Do(func() {
		server.HandleAuthenticated("GET /v1/history", http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
			query, err := ParseHistoryQuery(request.URL.Query(), time.Now())
			if err != nil {
				writePlain(writer, http.StatusBadRequest, err.Error()+"\n")
				return
			}
			result, err := server.catalog.History(request.Context(), query)
			if err != nil {
				writePlain(writer, http.StatusBadRequest, err.Error()+"\n")
				return
			}
			writeJSON(writer, result)
		}))
		server.HandleAuthenticated("GET /v1/history/metrics", http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
			result, err := server.catalog.Catalog(request.Context())
			if err != nil {
				writePlain(writer, http.StatusServiceUnavailable, "metric catalog unavailable\n")
				return
			}
			names := []string{}
			for _, metric := range result.Metrics {
				if metric.HistoryState == "available" {
					names = append(names, metric.Name)
				}
			}
			writeJSON(writer, names)
		}))
	})
}

func NewCollector(config CollectorConfig) (*Collector, error) {
	if config.Cell == "" || config.Member == "" || config.Role == "" {
		return nil, errors.New("observability collector requires a cell, member and role")
	}
	if config.MaxMetricsBytes <= 0 {
		config.MaxMetricsBytes = DefaultMaxMetricsBytes
	}
	if config.System == nil {
		filesystems := append([]FilesystemRole(nil), config.Filesystems...)
		config.System = func() (SystemView, error) { return ReadSystem(filesystems) }
	}
	collector := &Collector{config: config, startedAt: time.Now().UTC(), version: buildVersion()}
	collector.nats.TTL, collector.placement.TTL, collector.system.TTL = sectionCacheTTL, sectionCacheTTL, sectionCacheTTL
	collector.credentials.TTL = sectionCacheTTL
	config.Registry.RegisterWriter(collector.writeMetrics)
	return collector, nil
}

