func isObserveResource(view string) bool {
	return slices.Contains([]string{"regions", "region", "nodes", "node", "services", "service", "functions", "function", "volumes", "volume", "foundation"}, view)
}

func observeResourcePath(view, cell, node, service, volume, tenant, function string) (string, error) {
	for _, selector := range []string{cell, node, service, volume, tenant, function} {
		if len(selector) > 256 || strings.ContainsAny(selector, "/\\") || strings.IndexFunc(selector, unicode.IsControl) >= 0 || selector == "." || selector == ".." {
			return "", errors.New("resource selectors must be at most 256 characters without path separators or control characters")
		}
	}
	if view == "regions" {
		return "/v1/regions", nil
	}
	if view == "node" && node == "" {
		return "", errors.New("this observation requires --node NAME")
	}
	if view == "service" && service == "" {
		return "", errors.New("observe service requires --service ID (or ROLE with --node)")
	}
	if view == "volume" && volume == "" {
		return "", errors.New("observe volume requires --volume ID")
	}
	if view == "function" && (tenant == "" || function == "") {
		return "", errors.New("observe function requires --tenant ID and --function ID")
	}
	path := "/v1/regions/" + cell
	switch view {
	case "foundation":
		path += "/foundation"
	case "functions":
		path += "/functions"
	case "function":
		path += "/functions/" + tenant + "/" + function
	case "nodes":
		path += "/nodes"
	case "node":
		path += "/nodes/" + node
	case "services":
		if node != "" {
			path += "/nodes/" + node
		}
		path += "/services"
	case "service":
		if node != "" {
			path += "/nodes/" + node
		}
		path += "/services/" + service
	case "volumes":
		path += "/volumes"
	case "volume":
		path += "/volumes/" + volume
	}
	return path, nil
}

func observeLocalCell(data []byte) (string, error) {
	var regions []globalview.Region
	if err := json.Unmarshal(data, &regions); err != nil || len(regions) == 0 || regions[0].Cell == "" {
		return "", errors.New("regional API did not identify its local region")
	}
	return regions[0].Cell, nil
}

func observeResourceError(path string, status int, data []byte) bool {
	if !strings.HasPrefix(path, "/v1/regions/") || (status != http.StatusNotFound && status != http.StatusServiceUnavailable) {
		return false
	}
	var result globalview.ResourceView
	if json.Unmarshal(data, &result) != nil || result.Version != 1 {
		return false
	}
	return slices.Contains([]string{"stale", "missing", "truncated", "unavailable", "not_found"}, result.State)
}

func writeObserveResource(out io.Writer, view, format string, data []byte) (any, bool, error) {
	if view == "regions" || view == "region" {
		var regions []globalview.Region
		if view == "region" {
			var region globalview.Region
			if err := json.Unmarshal(data, &region); err != nil || region.Cell == "" {
				return nil, false, errors.New("invalid region observation JSON")
			}
			regions = []globalview.Region{region}
		} else if err := json.Unmarshal(data, &regions); err != nil {
			return nil, false, errors.New("invalid regional observation JSON")
		}
		partial := len(regions) == 0
		if format == "table" {
			fmt.Fprintln(out, "CELL\tSTATE\tOBSERVED\tTRUNCATED\tNODES\tREADY")
		}
		for _, region := range regions {
			state, observed, truncated, nodes, ready := region.ResourceState(true), "unknown", false, 0, 0
			if region.Rollup != nil {
				observed = region.Rollup.ObservedAt.Format(time.RFC3339)
				truncated = region.Rollup.Truncated
				nodes = region.Rollup.Totals.Nodes
				ready = region.Rollup.Totals.Ready
			}
			partial = partial || state != "current" || truncated
			if format == "table" {
				fmt.Fprintf(out, "%s\t%s\t%s\t%t\t%d\t%d\n", region.Cell, state, observed, truncated, nodes, ready)
			}
		}
		if view == "region" {
			return regions[0], partial, nil
		}
		return regions, partial, nil
	}
	var result globalview.ResourceView
	if err := json.Unmarshal(data, &result); err != nil || result.Version != 1 || !slices.Contains([]string{"current", "stale", "missing", "truncated", "unavailable", "not_found"}, result.State) {
		return nil, false, errors.New("invalid resource observation JSON")
	}
	partial := result.State != "current" || result.Truncated
	var raw struct {
		Data jsontext.Value `json:"data"`
	}
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, false, err
	}
	if format == "table" {
		observed := "unknown"
		if !result.ObservedAt.IsZero() {
			observed = result.ObservedAt.Format(time.RFC3339)
		}
		fmt.Fprintf(out, "CELL\t%s\tSTATE\t%s\tOBSERVED\t%s\tTRUNCATED\t%t\n", result.Cell, result.State, observed, result.Truncated)
		if string(raw.Data) != "null" {
			switch view {
			case "functions", "function":
				var functions []globalview.FunctionObservation
				if err := json.Unmarshal(raw.Data, &functions); err != nil {
					return nil, false, err
				}
				fmt.Fprintln(out, "TENANT\tFUNCTION\tREVISION\tDIGEST\tTASK\tSTATE\tACTIVE\tSUCCEEDED\tFAILED\tREJECTED\tOBSERVED")
				for _, function := range functions {
					active, succeeded, failed, rejected := "unknown", "unknown", "unknown", "unknown"
					if function.State == "observed" && function.Snapshot != nil {
						active, succeeded, failed, rejected = fmt.Sprint(function.Snapshot.Active), fmt.Sprint(function.Snapshot.Succeeded), fmt.Sprint(function.Snapshot.Failed), fmt.Sprint(function.Snapshot.Rejected)
					}
					fmt.Fprintf(out, "%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n", function.TenantID, function.FunctionID, function.Revision, function.Digest, function.TaskID, function.State, active, succeeded, failed, rejected, function.ObservedAt.Format(time.RFC3339))
				}
			case "nodes":
				var nodes []globalview.Node
				if err := json.Unmarshal(raw.Data, &nodes); err != nil {
					return nil, false, err
				}
				fmt.Fprintln(out, "NODE\tHEALTH\tREPORTED\tCPU CORES\tMEMORY bytes\tSERVICES")
				for _, node := range nodes {
					var roles []string
					for _, service := range node.Services {
						roles = append(roles, service.Role)
					}
					fmt.Fprintf(out, "%s\t%s\t%s\t%d\t%d\t%s\n", node.Name, node.Health, node.ReportedAt.Format(time.RFC3339), node.CPUCores, node.MemoryBytes, strings.Join(roles, ","))
				}
			case "services":
				var managed []swarmruntime.ServiceObservation
				if err := json.Unmarshal(raw.Data, &managed); err != nil {
					return nil, false, err
				}
				if len(managed) > 0 && managed[0].ServiceID != "" {
					fmt.Fprintln(out, "SERVICE\tROLE\tREQUESTED\tRUNNING\tREADY\tREQUESTED DIGEST\tUPDATE\tOBSERVED")
					for _, service := range managed {
						ready := "unknown"
						if service.Readiness == "observed" {
							ready = fmt.Sprint(service.ReadyReplicas)
						}
						fmt.Fprintf(out, "%s\t%s\t%d\t%d\t%s\t%s\t%s\t%s\n", service.ServiceID, service.Role, service.RequestedReplicas, service.RunningReplicas, ready, service.RequestedDigest, service.UpdateState, service.ObservedAt.Format(time.RFC3339))
					}
					break
				}
				var services []globalview.Service
				if err := json.Unmarshal(raw.Data, &services); err != nil {
					return nil, false, err
				}
				fmt.Fprintln(out, "ROLE\tEXECUTION STATE\tDIGEST")
				for _, service := range services {
					fmt.Fprintf(out, "%s\t%s\t%s\n", service.Role, service.State, service.Digest)
				}
			case "volumes":
				var volumes []globalview.Volume
				if err := json.Unmarshal(raw.Data, &volumes); err != nil {
					return nil, false, err
				}
				fmt.Fprintln(out, "VOLUME\tNODE\tSTATE\tDETAIL\tSINCE")
				for _, volume := range volumes {
					fmt.Fprintf(out, "%s\t%s\t%s\t%s\t%s\n", volume.ID, volume.Node, volume.State, volume.Detail, volume.Since.Format(time.RFC3339))
				}
			default:
				fmt.Fprintf(out, "DATA\t%s\n", raw.Data)
			}
		}
	}
	return jsontext.Value(data), partial, nil
}

func Handler(view *View) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /v1/regions", func(writer http.ResponseWriter, request *http.Request) {
		writeJSON(writer, view.Regions())
	})
	mux.HandleFunc("GET /v1/regions/{region}", func(writer http.ResponseWriter, request *http.Request) {
		region, ok := view.Region(request.PathValue("region"))
		if !ok {
			http.Error(writer, "region is not configured", http.StatusNotFound)
			return
		}
		writeJSON(writer, region)
	})
	mountDrilldowns(mux, view)
	mountFunctionViews(mux, view)
	return mux
}

func writeJSON(writer http.ResponseWriter, value any) {
	writer.Header().Set("Content-Type", "application/json")
	writer.Header().Set("Cache-Control", "no-store")
	writer.Header().Set("X-Content-Type-Options", "nosniff")
	_ = json.NewEncoder(writer).Encode(value)
}

func NewView(local string, regions func() []string, now func() time.Time) *View {
	if now == nil {
		now = time.Now
	}
	return &View{
		local:       normalize(local),
		regions:     regions,
		now:         now,
		rollups:     map[string]*Rollup{},
		persisted:   map[string]time.Time{},
		persistedAt: map[string]time.Time{},
		changed:     make(chan struct{}),
	}
}

// Regions lists local first, then every other listed region by cell.
func (v *View) Regions() []Region {
	v.mu.Lock()
	defer v.mu.Unlock()
	cells := v.listed()
	out := make([]Region, 0, len(cells))
	for _, cell := range cells {
		out = append(out, v.region(cell))
	}
	return out
}

// Region returns one listed region; false when cell is not listed.
func (v *View) Region(cell string) (Region, bool) {
	v.mu.Lock()
	defer v.mu.Unlock()
	cell = normalize(cell)
	if !slices.Contains(v.listed(), cell) {
		return Region{}, false
	}
	return v.region(cell), true
}

// Changed returns a channel closed on the next accepted rollup.
func (v *View) Changed() <-chan struct{} {
	v.mu.Lock()
	defer v.mu.Unlock()
	return v.changed
}

// Accept keeps r when it is newer than the held rollup of its cell.
func (v *View) Accept(r Rollup) bool {
	v.mu.Lock()
	defer v.mu.Unlock()
	if validate(r, v.now()) != nil {
		return false
	}
	held := v.rollups[r.Cell]
	if held != nil && !r.ObservedAt.After(held.ObservedAt) {
		return false
	}
	if held == nil && len(v.rollups) >= maxRegions {
		v.prune()
		if len(v.rollups) >= maxRegions {
			return false
		}
	}
	v.rollups[r.Cell] = &r
	close(v.changed)
	v.changed = make(chan struct{})
	return true
}

func (v *View) listed() []string {
	var others []string
	if v.regions != nil {
		for _, raw := range v.regions() {
			cell := normalize(raw)
			if cell == "" || cell == v.local || slices.Contains(others, cell) {
				continue
			}
			others = append(others, cell)
		}
	}
	slices.Sort(others)
	if v.local == "" {
		return others
	}
	return append([]string{v.local}, others...)
}

// region reads one listed cell. Callers hold mu.
func (v *View) region(cell string) Region {
	r := v.rollups[cell]
	return Region{
		Cell:   cell,
		Rollup: r,
		Stale:  r != nil && v.now().Sub(r.ObservedAt) > StaleAfter,
	}

func validate(r Rollup, now time.Time) error {
	if r.Version != Version {
		return fmt.Errorf("rollup version %d, want %d", r.Version, Version)
	}
	if token, err := protocol.RegionToken(r.Cell); err != nil || token != r.Cell {
		return fmt.Errorf("rollup cell %q is not a region token", r.Cell)
	}
	if r.ObservedAt.IsZero() || r.ObservedAt.After(now.Add(time.Minute)) {
		return fmt.Errorf("rollup observed_at %s is outside the clock window", r.ObservedAt)
	}
	return nil

func (region Region) ResourceState(found bool) string {
	switch {
	case region.Rollup == nil:
		return "missing"
	case region.Stale:
		return "stale"
	case !found && region.Rollup.Truncated:
		return "truncated"
	case !found:
		return "not_found"
	default:
		return "current"
	}
}

func mountDrilldowns(mux *http.ServeMux, view *View) {
	for _, resource := range []string{"nodes", "nodes/{node}", "nodes/{node}/services", "nodes/{node}/services/{service}", "volumes", "volumes/{volume}", "services", "services/{service}"} {
		mux.HandleFunc("GET /v1/regions/{region}/"+resource, func(writer http.ResponseWriter, request *http.Request) {
			region, listed := view.Region(request.PathValue("region"))
			result := ResourceView{Version: 1, Cell: region.Cell, State: "not_found"}
			if !listed {
				writeResource(writer, result, http.StatusNotFound)
				return
			}
			if region.Rollup == nil {
				result.State = "missing"
				writeResource(writer, result, http.StatusServiceUnavailable)
				return
			}
			result.ObservedAt, result.Truncated = region.Rollup.ObservedAt, region.Rollup.Truncated
			data, found := drilldownData(region.Rollup, resource, request)
			result.State, result.Data = region.ResourceState(found), data
			if resource == "services" || resource == "services/{service}" {
				observed := region.Rollup.ServicesObservedAt
				for _, service := range region.Rollup.Services {
					if resource == "services" || service.ServiceID == request.PathValue("service") {
						if service.ObservedAt.IsZero() || service.ObservedAt.Before(observed) {
							observed = service.ObservedAt
						}
					}
				}
				result.State = region.ManagedServiceState(found, observed)
				result.ObservedAt = observed
				if result.State == "unavailable" {
					result.Data, found = nil, false
				}
			}
			if (resource == "volumes" || resource == "volumes/{volume}") && region.Rollup.VolumesUnavailable {
				result.State, result.Data = "unavailable", nil
				found = false
			}
			status := http.StatusOK
			if !found {
				status = http.StatusServiceUnavailable
				if result.State == "not_found" {
					status = http.StatusNotFound
				}
			}
			writeResource(writer, result, status)
		})
	}
}

func drilldownData(rollup *Rollup, resource string, request *http.Request) (any, bool) {
	switch resource {
	case "services":
		return slices.Clone(rollup.Services), true
	case "services/{service}":
		if index := slices.IndexFunc(rollup.Services, func(service swarmruntime.ServiceObservation) bool {
			return service.ServiceID == request.PathValue("service")
		}); index >= 0 {
			return rollup.Services[index], true
		}
	case "nodes":
		return append([]Node{}, rollup.Nodes...), true
	case "volumes":
		return append([]Volume{}, rollup.Volumes...), true
	case "volumes/{volume}":
		if index := slices.IndexFunc(rollup.Volumes, func(volume Volume) bool { return volume.ID == request.PathValue("volume") }); index >= 0 {
			return rollup.Volumes[index], true
		}
	default:
		index := slices.IndexFunc(rollup.Nodes, func(node Node) bool { return node.Name == request.PathValue("node") })
		if index < 0 {
			return nil, false
		}
		node := rollup.Nodes[index]
		switch resource {
		case "nodes/{node}":
			return node, true
		case "nodes/{node}/services":
			return append([]Service{}, node.Services...), true
		case "nodes/{node}/services/{service}":
			if index := slices.IndexFunc(node.Services, func(service Service) bool { return service.Role == request.PathValue("service") }); index >= 0 {
				return node.Services[index], true
			}
		}
	}
	return nil, false
}

func writeResource(writer http.ResponseWriter, result ResourceView, status int) {
	writer.Header().Set("Content-Type", "application/json")
	writer.Header().Set("Cache-Control", "no-store")
	writer.Header().Set("X-Content-Type-Options", "nosniff")
	writer.WriteHeader(status)
	writeJSON(writer, result)
}

func mountFunctionViews(mux *http.ServeMux, view *View) {
	for _, path := range []string{"functions", "functions/{tenant}/{function}"} {
		mux.HandleFunc("GET /v1/regions/{region}/"+path, func(w http.ResponseWriter, r *http.Request) {
			region, listed := view.Region(r.PathValue("region"))
			result := ResourceView{Version: 1, Cell: region.Cell, State: "not_found"}
			found := false
			if listed && region.Rollup != nil {
				result.Truncated, result.ObservedAt = region.Rollup.Truncated, region.Rollup.FunctionsObservedAt
				if path == "functions" {
					found, result.Data = true, slices.Clone(region.Rollup.Functions)
					result.State = region.FunctionState(nil, true)
					for _, function := range region.Rollup.Functions {
						if state := region.FunctionState(&function, true); state != "current" {
							result.State = state
							break
						}
					}
				} else {
					var functions []FunctionObservation
					for _, function := range region.Rollup.Functions {
						if function.TenantID == r.PathValue("tenant") && function.FunctionID == r.PathValue("function") {
							functions = append(functions, function)
						}
					}
					found = len(functions) > 0
					result.State = region.FunctionState(nil, found)
					if found {
						result.Data = functions
						for _, function := range functions {
							if state := region.FunctionState(&function, true); state != "current" {
								result.State = state
							}
							if function.ObservedAt.Before(result.ObservedAt) {
								result.ObservedAt = function.ObservedAt
							}
						}
					}
				}
			} else if listed {
				result.State = "missing"
			}
			status := http.StatusOK
			if !found || result.State == "unavailable" && result.Data == nil {
				status = http.StatusServiceUnavailable
				if result.State == "not_found" {
					status = http.StatusNotFound
				}
			}
			writeResource(w, result, status)
		})
	}
}

func (region Region) FunctionState(observation *FunctionObservation, found bool) string {
	if region.Rollup != nil && region.Rollup.FunctionsObservedAt.IsZero() {
		return "unavailable"
	}
	state := region.ResourceState(found)
	if state != "current" && state != "not_found" {
		return state
	}
	observed := region.Rollup.FunctionsObservedAt
	if observation != nil {
		if observation.State != "observed" && observation.State != "unplaced" || observation.State == "observed" && observation.Snapshot == nil {
			return "unavailable"
		}
		observed = observation.ObservedAt
	}
	if observed.IsZero() || region.Rollup.ObservedAt.Sub(observed) > StaleAfter {
		return "stale"
	}
	return state
}

func (region Region) ManagedServiceState(found bool, observed time.Time) string {
	if region.Rollup != nil && region.Rollup.ServicesObservedAt.IsZero() {
		return "unavailable"
	}
	state := region.ResourceState(found)
	if state != "current" && state != "not_found" {
		return state
	}
	if observed.IsZero() || region.Rollup.ObservedAt.Sub(observed) > StaleAfter {
		return "stale"
	}
	return state
}

