// stubRefoundGuard gives refound a complete ledger and a survivor whose
// cluster view already reports controller-b current.
func stubRefoundGuard(t *testing.T, root string) membership.RefoundGuard {
	t.Helper()
	previousLedger, previousGuard, previousPoll, previousWait := refoundLedger, refoundGuard, refoundPoll, refoundWait
	t.Cleanup(func() {
		refoundLedger, refoundGuard, refoundPoll, refoundWait = previousLedger, previousGuard, previousPoll, previousWait
	})
	refoundLedger = func(context.Context) (map[string]membership.LedgerSlot, error) {
		return map[string]membership.LedgerSlot{"controller-a": {Attempt: 1, Complete: true},
			"controller-b": {Attempt: 1, Complete: true}, "controller-c": {Attempt: 1, Complete: true}}, nil
	}
	refoundGuard = membership.RefoundGuard{PendingPath: filepath.Join(root, "state", "refound-pending.json"),
		HealthPath: filepath.Join(root, "state", "cluster-health.json")}
	refoundPoll, refoundWait = time.Millisecond, time.Second
	// The survivor (metadata leader) reports b current with zero lag in a
	// view observed after the relaunch begins.
	if err := clusterhealth.WriteStatusFile(refoundGuard.HealthPath, clusterhealth.Status{
		ObservedAt: time.Now().UTC().Add(30 * time.Second), MetaLeader: "gru-1-ctl-1",
		Online: []string{"gru-1-ctl-1", "gru-1-ctl-2"}, CaughtUp: []string{"gru-1-ctl-2"}}); err != nil {
		t.Fatal(err)
	}
	return refoundGuard
}

// closedPort is a loopback port that refuses connections.
func closedPort(t *testing.T) string {
	t.Helper()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer listener.Close()
	return strconv.Itoa(listener.Addr().(*net.TCPAddr).Port)
}

// listenOn starts a listener on the config's client port, standing in for a
// running survivor broker.
func listenOn(t *testing.T, config string) net.Listener {
	t.Helper()
	data, err := os.ReadFile(config)
	if err != nil {
		t.Fatal(err)
	}
	var cfg struct {
		NATS struct {
			Embedded struct {
				Port int `json:"port"`
			} `json:"embedded"`
		} `json:"nats"`
	}
	if err := json.Unmarshal(data, &cfg); err != nil {
		t.Fatal(err)
	}
	listener, err := net.Listen("tcp", net.JoinHostPort("127.0.0.1", strconv.Itoa(cfg.NATS.Embedded.Port)))
	if err != nil {
		t.Fatal(err)
	}
	return listener
}

func runRecover(t *testing.T, args ...string) (string, error) {
	t.Helper()
	var output bytes.Buffer
	err := Run(t.Context(), append([]string{"cluster", "recover-quorum"}, args...), &output)
	return output.String(), err
}

func runCluster(ctx context.Context, args []string, out io.Writer) error {
	help := func(arg string) bool { return arg == "--help" || arg == "-h" || arg == "help" }
	if len(args) > 0 && !help(args[0]) && args[0] != "recover-quorum" {
		return fmt.Errorf("unknown cluster command %q", args[0])
	}
	if len(args) < 2 || help(args[0]) || help(args[1]) {
		_, err := io.WriteString(out, clusterUsage)
		return err
	}
	command, args := args[1], args[2:]
	allowed, known := recoverFlags[command]
	if !known {
		return fmt.Errorf("unknown recover-quorum command %q", command)
	}
	flags := flag.NewFlagSet("recover-quorum "+command, flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	configPath := flags.String("config", "", "survivor controller.json")
	destination := flags.String("out", "", "new absolute backup directory, or render-retirement output directory")
	backupDir := flags.String("dir", "", "backup directory to verify")
	slot := flags.String("slot", "", "lost peer slot to re-found")
	retirement := flags.String("retirement", "", "root-signed <slot>.retirement envelope")
	backup := flags.String("backup", "", "verified survivor backup directory")
	if err := flags.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			_, err := io.WriteString(out, clusterUsage)
			return err
		}
		return err
	}
	if flags.NArg() != 0 {
		return errors.New("recover-quorum takes only flags")
	}
	var unused []string
	flags.Visit(func(set *flag.Flag) {
		if !slices.Contains(allowed, set.Name) {
			unused = append(unused, "--"+set.Name)
		}
	})
	if len(unused) != 0 {
		return fmt.Errorf("recover-quorum %s does not take %s", command, strings.Join(unused, ", "))
	}
	if command == "verify-backup" {
		if *backupDir == "" {
			return errors.New("verify-backup requires --dir")
		}
		files, err := membership.VerifyBackup(*backupDir)
		if err != nil {
			return err
		}
		_, err = fmt.Fprintf(out, "backup %s verified: %d files\n", *backupDir, files)
		return err
	}
	if *configPath == "" {
		return fmt.Errorf("%s requires --config", command)
	}
	target, err := recoveryTarget(*configPath)
	if err != nil {
		return err
	}
	switch command {
	case "runbook":
		_, err := io.WriteString(out, membership.Runbook(target))
		return err
	case "preflight":
		_, err := membership.Preflight(ctx, target, out)
		return err
	}
	// Every changing command acts for the locally admitted controller, so
	// the recovery config must describe that controller before any check or
	// confirmation uses it.
	accepted, err := bindLocalAdmittedInstall(target)
	if err != nil {
		return err
	}
	switch command {
	case "backup":
		return membership.Backup(ctx, target, *destination, recoveryInput, out)
	case "render-retirement":
		if *slot == "" || *destination == "" || !filepath.IsAbs(*destination) {
			return errors.New("render-retirement requires --slot and an absolute --out directory")
		}
		if *slot == target.Slot {
			return errors.New("render-retirement cannot retire the local survivor slot")
		}
		path, err := renderRetirement(ctx, *slot, *destination)
		if err != nil {
			return fmt.Errorf("render %s retirement request: %w", *slot, err)
		}
		_, err = fmt.Fprintf(out, "wrote %s; root-sign it offline with ts-orch bootstrap sign-slot-retirement\n", path)
		return err
	default: // refound
		return refound(ctx, target, accepted, *slot, *retirement, *backup, out)
	}
}

func recoveryTarget(path string) (membership.RecoveryTarget, error) {
	cfg, err := app.LoadConfig(path)
	if err != nil {
		return membership.RecoveryTarget{}, err
	}
	embedded := cfg.NATS.Embedded
	if embedded == nil || cfg.NATS.Cell == "" || cfg.NATS.Instance == "" {
		return membership.RecoveryTarget{}, errors.New("recovery needs a controller config with an embedded broker")
	}
	// Without a fixed client and route port neither a stopped nor a
	// running broker can be established.
	if embedded.Port <= 0 || embedded.RoutePort <= 0 || embedded.Host == "" || embedded.RouteHost == "" {
		return membership.RecoveryTarget{}, errors.New("recovery needs the embedded broker's fixed client and route listeners")
	}
	return membership.RecoveryTarget{Cell: cfg.NATS.Cell, Slot: cfg.NATS.Instance, StoreDir: embedded.StoreDir,
		ClientAddress: net.JoinHostPort(embedded.Host, strconv.Itoa(embedded.Port)),
		RouteAddress:  net.JoinHostPort(embedded.RouteHost, strconv.Itoa(embedded.RoutePort))}, nil
}

// bindLocalAdmittedInstall requires the recovery config to name the cell,
// slot and broker address of the controller admitted on this host.
func bindLocalAdmittedInstall(target membership.RecoveryTarget) (bootstrapstart.AcceptedIdentity, error) {
	accepted, err := localAdmittedInstall()
	if err != nil {
		return bootstrapstart.AcceptedIdentity{}, fmt.Errorf("read the locally admitted controller: %w", err)
	}
	host, _, err := net.SplitHostPort(target.ClientAddress)
	if err != nil || !strings.EqualFold(accepted.Cell, target.Cell) || accepted.Slot != target.Slot ||
		accepted.PrimaryPrivateIP != host || accepted.Store.Directory != target.StoreDir {
		return bootstrapstart.AcceptedIdentity{}, fmt.Errorf(
			"--config describes %s/%s at %s, not the controller admitted on this host (%s/%s at %s)",
			target.Cell, target.Slot, host, accepted.Cell, accepted.Slot, accepted.PrimaryPrivateIP)
	}
	return accepted, nil
}

func readRetirementEvidence(path string) ([]byte, error) {
	file, err := os.OpenFile(path, os.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > maxRetirementEvidenceBytes {
		return nil, errors.New("retirement evidence must be a bounded regular file")
	}
	wire, err := io.ReadAll(io.LimitReader(file, maxRetirementEvidenceBytes+1))
	if err != nil {
		return nil, err
	}
	if len(wire) == 0 || len(wire) > maxRetirementEvidenceBytes {
		return nil, errors.New("retirement evidence must be a bounded regular file")
	}
	return wire, nil
}

func refound(ctx context.Context, target membership.RecoveryTarget, accepted bootstrapstart.AcceptedIdentity,
	slot, retirementPath, backup string, out io.Writer,
) error {
	if slot == "" || retirementPath == "" || backup == "" {
		return errors.New("refound requires --slot, --retirement and --backup")
	}
	if slot == target.Slot {
		return errors.New("refound cannot relaunch the local survivor slot")
	}
	// The data-bearing survivor must already run, so the empty replacement
	// joins its metadata group instead of forming one with another empty
	// replacement.
	if err := membership.BrokerRunning(ctx, target); err != nil {
		return err
	}
	// One slot at a time: no other slot may be mid-replacement in the
	// ledger, and the slot re-founded before must report current. The host
	// lock covers admission through the wait, so a concurrent refound for
	// another slot cannot pass admission on the same old ledger.
	release, err := refoundGuard.Lock()
	if err != nil {
		return err
	}
	defer release()
	ledger, err := refoundLedger(ctx)
	if err != nil {
		return fmt.Errorf("read the controller slot ledger: %w", err)
	}
	if err := refoundGuard.Admit(target.Cell, slot, ledger); err != nil {
		return err
	}
	files, err := membership.VerifyBackupFor(backup, target, time.Now(), membership.BackupMaxAge)
	if err != nil {
		return fmt.Errorf("refound requires a verified backup of this survivor: %w", err)
	}
	wire, err := readRetirementEvidence(retirementPath)
	if err != nil {
		return err
	}
	evidence, err := bootstrap.DecodeSlotRetirementCandidate(wire)
	if err != nil {
		return err
	}
	if evidence.Slot != slot {
		return errors.New("retirement evidence names a different slot")
	}
	fmt.Fprintf(out, "survivor backup %s verified (%d files)\nretiring %s attempt %d instance %s (signed observation %s)\n",
		backup, files, evidence.Slot, evidence.PreviousAttempt, evidence.PriorInstanceOCID,
		evidence.ObservedAt.Format("2006-01-02T15:04:05Z"))
	if err := membership.Confirm(ctx, recoveryInput, out,
		"this launches a new OCI instance for the slot at its old private IP. The retired instance must be TERMINATED.",
		"re-found "+target.Cell+"/"+slot); err != nil {
		return err
	}
	replacer, err := refoundReplacer(ctx, accepted)
	if err != nil {
		return err
	}
	serverName := membership.Topology{Cell: target.Cell}.ServerName(slot)
	pending := membership.RefoundPending{Cell: target.Cell, Slot: slot, ServerName: serverName,
		Attempt: evidence.PreviousAttempt + 1, StartedAt: time.Now().UTC()}
	if err := refoundGuard.Begin(pending); err != nil {
		return fmt.Errorf("record the pending refound: %w", err)
	}
	if err := replacer.Replace(ctx, slot, wire); err != nil {
		return fmt.Errorf("re-found %s: %w", slot, err)
	}
	fmt.Fprintf(out, "re-founded %s as attempt %d; waiting until it reports current\n", slot, evidence.PreviousAttempt+1)
	if err := refoundGuard.WaitCurrent(ctx, pending, refoundPoll, refoundWait, out); err != nil {
		return err
	}
	_, err = fmt.Fprintf(out, "%s reports current; the next lost slot may be re-founded\n", serverName)
	return err
}

func LoadConfig(path string) (Config, error) {
	if path == "" {
		return Config{}, errors.New("--config is required")
	}
	info, err := os.Stat(path)
	if err != nil {
		return Config{}, fmt.Errorf("stat config: %w", err)
	}
	if info.Size() > maxConfigBytes {
		return Config{}, errors.New("config is too large")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read config: %w", err)
	}
	cfg, err := decodeConfig(data)
	if err != nil {
		return Config{}, fmt.Errorf("parse config: %w", err)
	}
	if err := cfg.Observability.Validate(); err != nil {
		return Config{}, fmt.Errorf("observability config: %w", err)
	}
	if api := cfg.Controller.MachinesAPI; api != nil {
		if err := api.Validate(); err != nil {
			return Config{}, err
		}
	}
	return cfg, nil
}

// decodeConfig strictly decodes config bytes and keeps them as the config's wire.
func decodeConfig(data []byte) (Config, error) {
	var cfg Config
	if err := protocol.DecodeStrict(data, &cfg, maxConfigBytes); err != nil {
		return Config{}, err
	}
	if cfg.Version != ConfigVersion {
		return Config{}, fmt.Errorf("config version must be %d, got %d", ConfigVersion, cfg.Version)
	}
	cfg.wire = data
	return cfg, nil

func Confirm(ctx context.Context, in io.Reader, out io.Writer, warning, phrase string) error {
	if err := ctx.Err(); err != nil {
		return fmt.Errorf("confirmation was cancelled; nothing was changed: %w", err)
	}
	fmt.Fprintf(out, "\nWARNING: %s\nType %q to continue: ", warning, phrase)
	type answer struct {
		line string
		err  error
	}
	answered := make(chan answer, 1)
	go func() {
		line, err := bufio.NewReader(in).ReadString('\n')
		answered <- answer{line, err}
	}()
	var reply answer
	select {
	case <-ctx.Done():
		return fmt.Errorf("confirmation was cancelled; nothing was changed: %w", ctx.Err())
	case reply = <-answered:
	}
	if reply.err != nil {
		return fmt.Errorf("confirmation was not entered; nothing was changed: %w", reply.err)
	}
	if strings.TrimSpace(reply.line) != phrase {
		return errors.New("confirmation phrase did not match; nothing was changed")
	}
	return nil

func BrokerStopped(ctx context.Context, target RecoveryTarget) error {
	addresses, err := target.listeners()
	if err != nil {
		return err
	}
	dialer := net.Dialer{Timeout: time.Second}
	for _, address := range addresses {
		conn, err := dialer.DialContext(ctx, "tcp", address)
		if err == nil {
			conn.Close()
			return fmt.Errorf("embedded broker still accepts connections on %s; stop the controller service first", address)
		}
		if !errors.Is(err, syscall.ECONNREFUSED) {
			return fmt.Errorf("cannot establish that the broker on %s is stopped: %w", address, err)
		}
	}
	return nil
}

// BrokerRunning succeeds when an embedded broker listener accepts TCP. The
// data-bearing survivor must be running before any lost peer is re-founded,
// so an empty replacement can only join the survivor's metadata group and
// never forms a new one with another empty replacement.
func BrokerRunning(ctx context.Context, target RecoveryTarget) error {
	addresses, err := target.listeners()
	if err != nil {
		return err
	}
	dialer := net.Dialer{Timeout: time.Second}
	var last error
	for _, address := range addresses {
		conn, err := dialer.DialContext(ctx, "tcp", address)
		if err == nil {
			conn.Close()
			return nil
		}
		last = err
	}
	return fmt.Errorf("survivor broker is not accepting connections; start the survivor controller service first: %w", last)
}

func (target RecoveryTarget) listeners() ([]string, error) {
	var addresses []string
	for _, address := range []string{target.ClientAddress, target.RouteAddress} {
		if address == "" {
			continue
		}
		host, port, err := net.SplitHostPort(address)
		if err != nil || host == "" || port == "" || port == "0" || strings.HasPrefix(port, "-") {
			return nil, errNoBrokerListener
		}
		addresses = append(addresses, address)
	}
	if len(addresses) == 0 {
		return nil, errNoBrokerListener
	}
	return addresses, nil
}

// Preflight checks the survivor is stopped and inventories its store.
func Preflight(ctx context.Context, target RecoveryTarget, out io.Writer) (Inventory, error) {
	if target.Cell == "" || target.Slot == "" || target.StoreDir == "" || !filepath.IsAbs(target.StoreDir) {
		return Inventory{}, errors.New("recovery target needs a cell, slot and absolute store directory")
	}
	if _, err := target.listeners(); err != nil {
		return Inventory{}, err
	}
	if err := BrokerStopped(ctx, target); err != nil {
		return Inventory{}, err
	}
	inventory, err := inventoryStore(target.StoreDir)
	if err != nil {
		return Inventory{}, err
	}
	fmt.Fprintf(out, "survivor %s/%s store %s: %d files, %d bytes, metadata group present=%t\n",
		target.Cell, target.Slot, target.StoreDir, inventory.Files, inventory.Bytes, inventory.MetaGroup)
	accounts := make([]string, 0, len(inventory.Accounts))
	for account := range inventory.Accounts {
		accounts = append(accounts, account)
	}
	slices.Sort(accounts)
	for _, account := range accounts {
		fmt.Fprintf(out, "  account %s streams: %s\n", account, strings.Join(inventory.Accounts[account], ", "))
	}
	return inventory, nil
}

func inventoryStore(root string) (Inventory, error) {
	info, err := os.Lstat(root)
	if err != nil {
		return Inventory{}, err
	}
	if !info.IsDir() {
		return Inventory{}, errors.New("survivor store is not a directory")
	}
	inventory := Inventory{Accounts: make(map[string][]string)}
	err = filepath.WalkDir(root, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		relative, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		parts := strings.Split(filepath.ToSlash(relative), "/")
		if entry.IsDir() {
			if len(parts) == 4 && parts[0] == "jetstream" && parts[2] == "streams" {
				inventory.Accounts[parts[1]] = append(inventory.Accounts[parts[1]], parts[3])
			}
			if entry.Name() == "_meta_" {
				inventory.MetaGroup = true
			}
			return nil
		}
		if !entry.Type().IsRegular() {
			return fmt.Errorf("survivor store contains a non-regular file %s", relative)
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		inventory.Files++
		inventory.Bytes += info.Size()
		return nil
	})
	return inventory, err

func Backup(ctx context.Context, target RecoveryTarget, destination string, in io.Reader, out io.Writer) (err error) {
	if destination == "" || !filepath.IsAbs(destination) {
		return errors.New("backup destination must be an absolute path")
	}
	if _, err := os.Lstat(destination); err == nil {
		return errors.New("backup destination already exists")
	}
	// Compare physical paths: a symlinked ancestor must not place the
	// backup inside the store it copies (or the store inside the backup).
	store, err := filepath.EvalSymlinks(target.StoreDir)
	if err != nil {
		return fmt.Errorf("resolve survivor store: %w", err)
	}
	parent, err := filepath.EvalSymlinks(filepath.Dir(destination))
	if err != nil {
		return fmt.Errorf("resolve backup destination parent: %w", err)
	}
	physical := filepath.Join(parent, filepath.Base(destination))
	if within(physical, store) || within(store, physical) ||
		within(destination, target.StoreDir) || within(target.StoreDir, destination) {
		return errors.New("backup destination must be outside the survivor store")
	}
	inventory, err := Preflight(ctx, target, out)
	if err != nil {
		return err
	}
	if err := Confirm(ctx, in, out, "this copies the stopped survivor store. Keep the controller stopped until recovery ends.",
		"back up "+target.Cell+"/"+target.Slot); err != nil {
		return err
	}
	if err := os.Mkdir(physical, 0o700); err != nil {
		return err
	}
	defer func() {
		if err != nil {
			_ = os.RemoveAll(physical)
		}
	}()
	var manifest []string
	var copiedBytes int64
	err = filepath.WalkDir(target.StoreDir, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if err := ctx.Err(); err != nil {
			return err
		}
		relative, err := filepath.Rel(target.StoreDir, path)
		if err != nil || relative == "." {
			return err
		}
		copied := filepath.Join(physical, relative)
		if entry.IsDir() {
			return os.Mkdir(copied, 0o700)
		}
		if !entry.Type().IsRegular() {
			return fmt.Errorf("survivor store contains a non-regular file %s", relative)
		}
		sum, size, err := copyFile(path, copied)
		if err != nil {
			return err
		}
		copiedBytes += size
		manifest = append(manifest, sum+"  "+filepath.ToSlash(relative))
		return nil
	})
	if err != nil {
		return fmt.Errorf("back up survivor store: %w", err)
	}
	if err := BrokerStopped(ctx, target); err != nil {
		return fmt.Errorf("broker started during backup: %w", err)
	}
	if len(manifest) != inventory.Files || copiedBytes != inventory.Bytes {
		return fmt.Errorf("survivor store changed during backup: inventoried %d files (%d bytes), copied %d files (%d bytes)",
			inventory.Files, inventory.Bytes, len(manifest), copiedBytes)
	}
	slices.Sort(manifest)
	header := backupProvenance{Cell: target.Cell, Slot: target.Slot, StoreDir: target.StoreDir,
		TakenAt: time.Now().UTC().Truncate(time.Second)}.lines()
	if err := writeSynced(filepath.Join(physical, BackupManifestName),
		[]byte(strings.Join(append(header, manifest...), "\n")+"\n")); err != nil {
		return err
	}
	fmt.Fprintf(out, "backed up %d files to %s\n", len(manifest), destination)
	return nil
}

func VerifyBackup(dir string) (int, error) {
	_, files, err := verifyBackup(dir)
	return files, err
}

// VerifyBackupFor verifies a backup and that it was taken from target's
// store within maxAge of now.
func VerifyBackupFor(dir string, target RecoveryTarget, now time.Time, maxAge time.Duration) (int, error) {
	provenance, files, err := verifyBackup(dir)
	if err != nil {
		return 0, err
	}
	if provenance.Cell != target.Cell || provenance.Slot != target.Slot || provenance.StoreDir != target.StoreDir {
		return 0, fmt.Errorf("backup was taken from %s/%s store %s, not this survivor",
			provenance.Cell, provenance.Slot, provenance.StoreDir)
	}
	if provenance.TakenAt.IsZero() || provenance.TakenAt.After(now.Add(time.Minute)) ||
		now.Sub(provenance.TakenAt) > maxAge {
		return 0, fmt.Errorf("backup taken at %s is not a current survivor backup",
			provenance.TakenAt.Format(time.RFC3339))
	}
	return files, nil
}

func verifyBackup(dir string) (backupProvenance, int, error) {
	data, err := os.ReadFile(filepath.Join(dir, BackupManifestName))
	if err != nil {
		return backupProvenance{}, 0, fmt.Errorf("read backup manifest: %w", err)
	}
	var provenance backupProvenance
	want := make(map[string]string)
	for _, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
		if header, ok := strings.CutPrefix(line, backupProvenancePrefix); ok {
			key, value, _ := strings.Cut(header, " ")
			switch key {
			case "cell":
				provenance.Cell = value
			case "slot":
				provenance.Slot = value
			case "store":
				provenance.StoreDir = value
			case "taken":
				provenance.TakenAt, _ = time.Parse(time.RFC3339, value)
			default:
				return backupProvenance{}, 0, errors.New("backup manifest is malformed")
			}
			continue
		}
		sum, name, ok := strings.Cut(line, "  ")
		if !ok || len(sum) != 64 || !validBackupName(name) {
			return backupProvenance{}, 0, errors.New("backup manifest is malformed")
		}
		if _, duplicate := want[name]; duplicate {
			return backupProvenance{}, 0, fmt.Errorf("backup manifest lists %s twice", name)
		}
		want[name] = sum
	}
	seen := 0
	err = filepath.WalkDir(dir, func(path string, entry fs.DirEntry, err error) error {
		if err != nil || entry.IsDir() {
			return err
		}
		relative, err := filepath.Rel(dir, path)
		if err != nil {
			return err
		}
		relative = filepath.ToSlash(relative)
		if relative == BackupManifestName {
			return nil
		}
		expected, ok := want[relative]
		if !ok || !entry.Type().IsRegular() {
			return fmt.Errorf("backup contains unlisted file %s", relative)
		}
		sum, err := fileSHA256(path)
		if err != nil {
			return err
		}
		if sum != expected {
			return fmt.Errorf("backup file %s digest differs", relative)
		}
		seen++
		return nil
	})
	if err != nil {
		return backupProvenance{}, 0, err
	}
	if seen != len(want) {
		return backupProvenance{}, 0, errors.New("backup is missing listed files")
	}
	return provenance, seen, nil

func copyFile(source, destination string) (string, int64, error) {
	input, err := os.Open(source)
	if err != nil {
		return "", 0, err
	}
	defer input.Close()
	output, err := os.OpenFile(destination, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return "", 0, err
	}
	hash := sha256.New()
	size, err := io.Copy(io.MultiWriter(output, hash), input)
	if err != nil {
		output.Close()
		return "", 0, err
	}
	if err := output.Sync(); err != nil {
		output.Close()
		return "", 0, err
	}
	if err := output.Close(); err != nil {
		return "", 0, err
	}
	return hex.EncodeToString(hash.Sum(nil)), size, nil
}

func fileSHA256(path string) (string, error) {
	file, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer file.Close()
	hash := sha256.New()
	if _, err := io.Copy(hash, file); err != nil {
		return "", err
	}
	return hex.EncodeToString(hash.Sum(nil)), nil
}

func writeSynced(path string, data []byte) error {
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return err
	}
	if _, err := file.Write(data); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	return file.Close()
}

// Admit refuses to re-found slot while another slot is mid-replacement.
func (guard RefoundGuard) Admit(cell, slot string, ledger map[string]LedgerSlot) error {
	others := make([]string, 0, len(ledger))
	for other := range ledger {
		others = append(others, other)
	}
	slices.Sort(others)
	for _, other := range others {
		head := ledger[other]
		if other != slot && !head.Complete && head.Attempt >= 2 {
			return fmt.Errorf("slot %s has an incomplete re-founded attempt %d; wait until it completes and reports current before re-founding %s",
				other, head.Attempt, slot)
		}
	}
	pending, err := guard.readPending()
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("read the pending refound record %s: %w", guard.PendingPath, err)
	}
	if pending.Cell != cell {
		return fmt.Errorf("pending refound belongs to cell %s, not %s", pending.Cell, cell)
	}
	if pending.Slot == slot {
		// The same slot may be retried after interruption.
		return nil
	}
	if err := guard.current(pending); err != nil {
		return fmt.Errorf("slot %s re-founded at %s is not current yet (%v); re-found one slot at a time",
			pending.Slot, pending.StartedAt.Format(time.RFC3339), err)
	}
	return guard.Clear()
}

// Begin records slot as the re-found in progress before any launch.
func (guard RefoundGuard) Begin(pending RefoundPending) error {
	if err := pending.validate(); err != nil {
		return err
	}
	wire, err := json.Marshal(pending)
	if err != nil {
		return err
	}
	return writeOwnerOnly(guard.PendingPath, wire)
}

// Clear removes the pending record.
func (guard RefoundGuard) Clear() error {
	if err := os.Remove(guard.PendingPath); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	return syncDir(filepath.Dir(guard.PendingPath))
}

// WaitCurrent polls the controller's cluster health until the pending
// slot's server is an online, caught-up metadata peer in a view observed
// after the relaunch began, then clears the pending record. On timeout the
// record stays, so no other slot is re-founded meanwhile.
func (guard RefoundGuard) WaitCurrent(ctx context.Context, pending RefoundPending, poll, timeout time.Duration,
	out io.Writer,
) error {
	serverName := pending.ServerName
	deadline := guard.now().Add(timeout)
	last := ""
	for {
		err := guard.current(pending)
		if err == nil {
			return guard.Clear()
		}
		if err.Error() != last {
			last = err.Error()
			fmt.Fprintf(out, "waiting for %s to report current: %v\n", serverName, err)
		}
		if !guard.now().Before(deadline) {
			return fmt.Errorf("%s did not report current within %s (%v); rerun refound for the same slot to keep waiting before re-founding another",
				serverName, timeout, err)
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(poll):
		}
	}
}

// current judges the pending slot from a cluster view that is both fresh and
// observed after the relaunch began: the successor reuses the lost
// instance's server name, so an earlier view says nothing about it.
func (guard RefoundGuard) current(pending RefoundPending) error {
	if err := pending.validate(); err != nil {
		return err
	}
	status, err := clusterhealth.ReadStatusFile(guard.HealthPath)
	if err != nil {
		return fmt.Errorf("read the controller's cluster health %s: %w", guard.HealthPath, err)
	}
	notBefore := guard.now().Add(-RefoundHealthFreshness)
	if pending.StartedAt.After(notBefore) {
		notBefore = pending.StartedAt
	}
	return status.PeerCurrent(pending.ServerName, notBefore)
}

func (guard RefoundGuard) Lock() (release func(), err error) {
	path := guard.PendingPath + ".lock"
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return nil, err
	}
	file, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|syscall.O_NOFOLLOW, 0o600)
	if err != nil {
		return nil, fmt.Errorf("open the refound lock %s: %w", path, err)
	}
	if err := syscall.Flock(int(file.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		file.Close()
		if errors.Is(err, syscall.EWOULDBLOCK) {
			return nil, errors.New("another break-glass refound is running on this host; re-found one slot at a time")
		}
		return nil, fmt.Errorf("lock %s: %w", path, err)
	}
	return func() {
		_ = syscall.Flock(int(file.Fd()), syscall.LOCK_UN)
		file.Close()
	}, nil
}

func (guard RefoundGuard) readPending() (RefoundPending, error) {
	file, err := os.OpenFile(guard.PendingPath, os.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return RefoundPending{}, err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return RefoundPending{}, err
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 || info.Size() <= 0 || info.Size() > 4<<10 {
		return RefoundPending{}, errors.New("pending refound record must be a small owner-only regular file")
	}
	wire, err := io.ReadAll(io.LimitReader(file, (4<<10)+1))
	if err != nil {
		return RefoundPending{}, err
	}
	var pending RefoundPending
	if err := protocol.DecodeStrict(wire, &pending, 4<<10); err != nil {
		return RefoundPending{}, errors.New("pending refound record is malformed")
	}
	if err := pending.validate(); err != nil {
		return RefoundPending{}, err
	}
	return pending, nil
}

func writeOwnerOnly(path string, data []byte) error {
	dir := filepath.Dir(path)
	if _, err := os.Stat(dir); errors.Is(err, os.ErrNotExist) {
		if err := os.MkdirAll(dir, 0o700); err != nil {
			return err
		}
		if err := syncDir(filepath.Dir(dir)); err != nil {
			return err
		}
	}
	temporary, err := os.CreateTemp(dir, ".refound-*")
	if err != nil {
		return err
	}
	defer os.Remove(temporary.Name())
	if err := temporary.Chmod(0o600); err != nil {
		temporary.Close()
		return err
	}
	if _, err := temporary.Write(data); err != nil {
		temporary.Close()
		return err
	}
	if err := temporary.Sync(); err != nil {
		temporary.Close()
		return err
	}
	if err := temporary.Close(); err != nil {
		return err
	}
	if err := os.Rename(temporary.Name(), path); err != nil {
		return err
	}
	// The record gates the next slot after a crash, so its directory entry
	// must be durable before the caller launches anything.
	return syncDir(dir)
}

func syncDir(dir string) error {
	handle, err := os.Open(dir)
	if err != nil {
		return err
	}
	defer handle.Close()
	return handle.Sync()
}

func WriteStatusFile(path string, status Status) error {
	if path == "" || !filepath.IsAbs(path) {
		return errors.New("cluster health status file path must be absolute")
	}
	wire, err := json.Marshal(status)
	if err != nil {
		return err
	}
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}
	temporary, err := os.CreateTemp(dir, ".cluster-health-*")
	if err != nil {
		return err
	}
	defer os.Remove(temporary.Name())
	if err := temporary.Chmod(0o600); err != nil {
		temporary.Close()
		return err
	}
	if _, err := temporary.Write(wire); err != nil {
		temporary.Close()
		return err
	}
	if err := temporary.Close(); err != nil {
		return err
	}
	return os.Rename(temporary.Name(), path)
}

// ReadStatusFile reads a status written by WriteStatusFile. The file must be
// a bounded regular file that is not a symbolic link.
func ReadStatusFile(path string) (Status, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return Status{}, err
	}
	if !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > maxStatusFileBytes {
		return Status{}, errors.New("cluster health status must be a bounded regular file")
	}
	file, err := os.Open(path)
	if err != nil {
		return Status{}, err
	}
	defer file.Close()
	wire, err := io.ReadAll(io.LimitReader(file, maxStatusFileBytes+1))
	if err != nil {
		return Status{}, err
	}
	if len(wire) > maxStatusFileBytes {
		return Status{}, errors.New("cluster health status must be a bounded regular file")
	}
	var status Status
	if err := json.Unmarshal(wire, &status); err != nil {
		return Status{}, fmt.Errorf("decode cluster health status: %w", err)
	}
	return status, nil
}

// PeerCurrent reports whether serverName is an online, caught-up member of a
// metadata group that has a leader, as of a status observed no earlier than
// notBefore.
func (status Status) PeerCurrent(serverName string, notBefore time.Time) error {
	switch {
	case status.ObservedAt.Before(notBefore):
		return fmt.Errorf("cluster health was last observed at %s; is the controller running?",
			status.ObservedAt.Format(time.RFC3339))
	case status.MetaLeader == "":
		return errors.New("the metadata group has no leader")
	case slices.Contains(status.Missing, serverName):
		return fmt.Errorf("%s has not joined the metadata group", serverName)
	case slices.Contains(status.Offline, serverName) || !slices.Contains(status.Online, serverName):
		return fmt.Errorf("%s is offline", serverName)
	case slices.ContainsFunc(status.Lagging, func(peer LaggingPeer) bool { return peer.Name == serverName }):
		return fmt.Errorf("%s is still catching up", serverName)
	case !slices.Contains(status.CaughtUp, serverName):
		// Not lagging is not caught up: a lag within the alert threshold,
		// or a follower's view of another follower, proves nothing.
		return fmt.Errorf("%s has not been reported current with zero lag by the metadata leader in this controller's view",
			serverName)
	}
	return nil
}

func DecodeSlotRetirementCandidate(wire []byte) (RetirementEvidence, error) {
	if len(wire) == 0 || len(wire) > maxLedgerRecordBytes {
		return RetirementEvidence{}, ErrRetirementInvalid
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil || envelope.Scope.Domain != domainSlotRetirement {
		return RetirementEvidence{}, ErrRetirementInvalid
	}
	var evidence RetirementEvidence
	if err := decodeCanonicalPayload(envelope.Payload, &evidence); err != nil {
		return RetirementEvidence{}, ErrRetirementInvalid
	}
	if err := ValidateSlotRetirementCandidate(evidence); err != nil {
		return RetirementEvidence{}, err
	}
	if envelope.Scope != (trust.Scope{Domain: domainSlotRetirement, DeploymentID: evidence.DeploymentID,
		Cell: evidence.Cell, Environment: evidence.Environment, Role: roleController, Slot: evidence.Slot}) {
		return RetirementEvidence{}, ErrRetirementInvalid
	}
	return evidence, nil
}
